def gen(rng):
    def fmt(n, edges):
        return str(n) + '\n' + '\n'.join(f'{u} {v}' for u, v in edges)

    def relabel(n, edges):
        perm = list(range(n))
        rng.shuffle(perm)
        out = [(perm[u], perm[v]) if rng.random() < 0.5 else (perm[v], perm[u]) for u, v in edges]
        rng.shuffle(out)
        return fmt(n, out)

    def rand_tree(n, mode):
        edges = []
        for i in range(1, n):
            if mode == 'random':
                p = rng.randint(0, i - 1)
            elif mode == 'deep':
                p = rng.randint(max(0, i - 3), i - 1)
            else:
                p = 0
            edges.append((p, i))
        return edges

    tests = [
        '1',
        fmt(2, [(0, 1)]),
        fmt(3, [(1, 0), (1, 2)]),
        fmt(5, [(0, i) for i in range(1, 5)]),
        fmt(6, [(i, i + 1) for i in range(5)]),
    ]
    for n in (4, 5, 6, 7, 8, 10, 12, 15):
        for mode in ('random', 'deep', 'star'):
            if rng.random() < 0.6:
                tests.append(relabel(n, rand_tree(n, mode)))
    n = 100000
    tests.append(relabel(n, [(i, i + 1) for i in range(n - 1)]))
    tests.append(relabel(n, rand_tree(n, 'random')))
    tests.append(relabel(n, rand_tree(n, 'deep')))
    tests.append(relabel(n, rand_tree(n, 'star')))
    # two long arms joined by a short bridge off the middle
    edges = [(i, i + 1) for i in range(0, 49999)]
    for j in range(50000, n):
        edges.append((25000 if j == 50000 else j - 1, j))
    tests.append(relabel(n, edges))
    return tests
